import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import org.junit.Test;
import net.revelc.code.formatter.ConfigurationSource;
import net.revelc.code.formatter.LineEnding;

public class CssFormatterTest {

    @Test
    public void init_ValidInput_NoException() {
        CssFormatter cssFormatter = new CssFormatter();
        Map<String, String> options = new HashMap<String, String>();
        ConfigurationSource cfg = mock(ConfigurationSource.class);

        cssFormatter.init(options, cfg);

        assertNotNull(cssFormatter);
        verify(cfg).getCharset();
    }

    @Test
    public void doFormat_WithCodeAndEnding_FormatsWithoutException() throws IOException {
        CssFormatter cssFormatter = new CssFormatter();

        String result = cssFormatter.doFormat("body { background-color: blue; }", LineEnding.CRLF);

        assertNotNull(result);
        assertEquals("body {background-color: blue;}\r\n", result);
    }

    @Test(expected = IOException.class)
    public void doFormat_WithInvalidCSS_ThrowsIOException() throws IOException {
        CssFormatter cssFormatter = new CssFormatter();

        cssFormatter.doFormat("<div> { background-color blue; }", LineEnding.CRLF);
    }

    @Test
    public void isInitialized_FreshObject_ReturnsFalse() {
        CssFormatter cssFormatter = new CssFormatter();

        assertEquals(false, cssFormatter.isInitialized());
    }

    @Test
    public void isInitialized_AfterInit_ReturnsTrue() {
        CssFormatter cssFormatter = new CssFormatter();
        Map<String, String> options = new HashMap<String, String>();
        ConfigurationSource cfg = mock(ConfigurationSource.class);

        cssFormatter.init(options, cfg);

        assertEquals(true, cssFormatter.isInitialized());
    }
}
